from enum import Enum
from typing import List, Dict, Any
from pydantic import BaseModel, Field


class AuditVerdict(str, Enum):
    PASS = "PASS"
    REJECT = "REJECT"
    WARNING = "WARNING"


class CheatPattern(str, Enum):
    FORCED_EXIT = "FORCED_EXIT"
    EXCEPTION_SUPPRESSION = "EXCEPTION_SUPPRESSION"
    ENDPOINT_REMOVAL = "ENDPOINT_REMOVAL"
    AUTH_DISABLED = "AUTH_DISABLED"
    TRIVIAL_NOOP = "TRIVIAL_NOOP"
    TIMEOUT_INDUCED = "TIMEOUT_INDUCED"


class CriticAuditResult(BaseModel):
    """Output generated by Critic Agent."""
    verdict: AuditVerdict
    detected_cheats: List[CheatPattern] = Field(default_factory=list)
    reasons: List[str] = Field(default_factory=list)
    ast_diff_summary: str = ""
    remediation_guidance: str = ""
    metadata: Dict[str, Any] = Field(default_factory=dict)
